window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-5d0a786c6b7dc42f"]={"versions": [{"id": "FIG-5d0a786c6b7dc42f", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Methodik-Aktivitätsdiagramm (AUTOSAR Methodology Activity View / SPEM-basiertes Prozessdiagramm) zur Darstellung der Generierung von Basissoftware-Konfigurationscode im Rahmen des AUTOSAR-ECU-Konfigurationsprozesses.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Aktivität</strong>:</li>\n<li><code>Generate BSW Configuration Code</code> (zentrale Transformations- / Code-Generierungsaktivität)</li>\n<li><strong>Eingangs-Artefakt</strong>:</li>\n<li><code>ECU Configuration Values</code> (Kardinalität <code>1</code>, Stereotyp <code>«input»</code>)</li>\n<li><strong>Ausgangs-Artefakte</strong>:</li>\n<li><code>BSW Module Configuration Data Source Code</code> (oben rechts, Kardinalität <code>1</code>, Stereotyp <code>«output»</code>)</li>\n<li><code>BSW Module [Configuration Source Code]</code> (unten rechts abgeschnitten als <code>BSW Module</code>, Kardinalität <code>1</code>, Stereotyp <code>«output»</code>)</li>\n<li><strong>Beziehungen</strong>:</li>\n<li>Gerichtete Kontroll-/Datenflusskanten von den Eingangsdaten zur Aktivität und von der Aktivität zu den beiden Ziel-Code-Artefakten.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Die Aktivität <code>Generate BSW Configuration Code</code> nimmt genau eine Instanz der <code>ECU Configuration Values</code> entgegen.</li>\n<li>Der BSW-Code-Generator überführt die Konfigurationswerte in modulspezifische Implementierungs- und Konfigurationsdateien.</li>\n<li>Als Resultat werden parallel bzw. deterministisch zwei Artefakte erzeugt: Konfigurationsdaten-Quellcode (<code>BSW Module Configuration Data Source Code</code>) sowie weiterer BSW-Modulquellcode (ausgewiesen als <code>BSW Module</code>).</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Verbindlicher Workflowschritt bei der ECU-Integration zur Überführung der herstellerspezifisch validierten und parametrierten ECU-Konfiguration in C-Quell- und Headerdateien.</li>\n<li>Die strikte 1:1-Beziehung zu den Ausgangsartefakten erfordert, dass die Generatortools für jedes konfigurierte BSW-Modul die entsprechenden Cfg-Quelldateien konsistent zu den <code>ECU Configuration Values</code> bereitstellen.</li>\n</ul>"}, {"id": "FIG-5bb08d69b945f39d", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Methodik-Aktivitätsdiagramm (AUTOSAR Methodology Activity View / SPEM-basiertes Prozessdiagramm) zur Darstellung der Generierung von Basissoftware-Konfigurationscode im Rahmen des AUTOSAR-ECU-Konfigurationsprozesses.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Aktivität</strong>:</li>\n<li><code>Generate BSW Configuration Code</code> (zentrale Transformations- / Code-Generierungsaktivität)</li>\n<li><strong>Eingangs-Artefakt</strong>:</li>\n<li><code>ECU Configuration Values</code> (Kardinalität <code>1</code>, Stereotyp <code>«input»</code>)</li>\n<li><strong>Ausgangs-Artefakte</strong>:</li>\n<li><code>BSW Module Configuration Data Source Code</code> (oben rechts, Kardinalität <code>1</code>, Stereotyp <code>«output»</code>)</li>\n<li><code>BSW Module [Configuration Source Code]</code> (unten rechts abgeschnitten als <code>BSW Module</code>, Kardinalität <code>1</code>, Stereotyp <code>«output»</code>)</li>\n<li><strong>Beziehungen</strong>:</li>\n<li>Gerichtete Kontroll-/Datenflusskanten von den Eingangsdaten zur Aktivität und von der Aktivität zu den beiden Ziel-Code-Artefakten.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Die Aktivität <code>Generate BSW Configuration Code</code> nimmt genau eine Instanz der <code>ECU Configuration Values</code> entgegen.</li>\n<li>Der BSW-Code-Generator überführt die Konfigurationswerte in modulspezifische Implementierungs- und Konfigurationsdateien.</li>\n<li>Als Resultat werden parallel bzw. deterministisch zwei Artefakte erzeugt: Konfigurationsdaten-Quellcode (<code>BSW Module Configuration Data Source Code</code>) sowie weiterer BSW-Modulquellcode (ausgewiesen als <code>BSW Module</code>).</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Verbindlicher Workflowschritt bei der ECU-Integration zur Überführung der herstellerspezifisch validierten und parametrierten ECU-Konfiguration in C-Quell- und Headerdateien.</li>\n<li>Die strikte 1:1-Beziehung zu den Ausgangsartefakten erfordert, dass die Generatortools für jedes konfigurierte BSW-Modul die entsprechenden Cfg-Quelldateien konsistent zu den <code>ECU Configuration Values</code> bereitstellen.</li>\n</ul>"}], "trans": [{"from": "FIG-5d0a786c6b7dc42f", "to": "FIG-5bb08d69b945f39d", "fr": "R4.0.3", "tr": "R4.1.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
